// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.36;

uint256 constant CASTED = uint256(42);
int256 constant NEGATIVE = -42;
int256 constant POSITIVE_SIGNED = 64;
type MyUint is uint128;
MyUint constant WRAPPED = MyUint.wrap(42);
function layoutBase() pure returns (uint256) { return 128; }

contract Collision { error gsf(); error tgeo(); }
contract CallIsNotConstant layout at layoutBase() {}
contract AddressLayout layout at address(0x1234) {}
contract FixedBytesLayout layout at bytes1(0x12) {}
contract UserDefinedLayout layout at WRAPPED {}
contract FractionalLayout layout at 3 / 2 {}
contract CastRemainsUnsupported layout at CASTED {}
contract ConditionalRemainsUnsupported layout at (true ? 1 : 2) {}
contract TypeMemberRemainsUnsupported layout at type(uint256).max {}
contract NegativeLayout layout at NEGATIVE {}
contract SignedLayout layout at POSITIVE_SIGNED {}
contract OverflowLayout layout at 2**256 {}
contract ExtendsPastEnd layout at 2**256 - 2 { uint256 x; bool y; }
